import { useMemo } from 'react'
import { DsShellApp } from '@ds-mo/ui/react'
import { PANEL_TOOLS_DEFAULT_ITEMS } from '@ds-mo/ui/shell'
import type { ShellNavigationConfig, ShellPageChromeConfig } from '@ds-mo/ui/shell'

export function AppShell({ route, navigate, children }) {
  const navigation = useMemo<ShellNavigationConfig>(() => ({ groups: route.groups, dashboardGroups: route.dashboardGroups, settingsGroups: route.settingsGroups, currentUrl: route.url, browseContext: route.context, routerMode: 'event', userName: route.user.name, userInitial: route.user.initial }), [route])
  const pageChrome = useMemo<ShellPageChromeConfig>(() => ({ heading: route.heading, tabs: route.sections, value: route.section, currentUrl: route.url }), [route])
  return <DsShellApp navigation={navigation} pageChrome={pageChrome} tools={{ items: PANEL_TOOLS_DEFAULT_ITEMS }} onDsNavSelect={event => navigate(event.detail)} onDsTabChange={event => navigate(event.detail)}>
    <SearchProduct slot="search-view" />
    <AgentsProduct slot="agents-view" />
    <InboxProduct slot="messages-view" />
    <HelpProduct slot="help-view" />
    {children}
  </DsShellApp>
}

import { Component } from '@angular/core'
import { Router, RouterOutlet } from '@angular/router'
import { DsShellApp } from '@ds-mo/ui/angular/ds-shell-app'
import { PANEL_TOOLS_DEFAULT_ITEMS } from '@ds-mo/ui/shell'
import type { ShellNavigationConfig, ShellPageChromeConfig, ShellToolsConfig } from '@ds-mo/ui/shell'

@Component({ selector: 'app-shell', standalone: true, imports: [DsShellApp, RouterOutlet], templateUrl: './app-shell.component.html' })
export class AppShellComponent {
  navigation: ShellNavigationConfig = { groups: [], dashboardGroups: [], settingsGroups: [], routerMode: 'event' }
  pageChrome: ShellPageChromeConfig = { heading: '' }
  tools: ShellToolsConfig = { items: PANEL_TOOLS_DEFAULT_ITEMS }
  constructor(private router: Router) {}
  navigate(target: string) { void this.router.navigateByUrl(target) }
}
